import time

def fetch_with_retry(fetch, attempts: int = 3, delay: float = 0.5):
    last_error = None
    for i in range(attempts):
        try:
            return fetch()
        except ConnectionError as e:
            last_error = e
            time.sleep(delay * (2 ** i))
    raise last_error
```

